const BN254_G1_SERIALIZED_SIZE: usize = 64;
const BN254_G2_SERIALIZED_SIZE: usize = 128;
const BN254_FR_SERIALIZED_SIZE: usize = 32;

#[derive(Clone)]
#[contracttype]
pub struct Proof {
    pub a: [u8; BN254_G1_SERIALIZED_SIZE],
    pub b: [u8; BN254_G2_SERIALIZED_SIZE],
    pub c: [u8; BN254_G1_SERIALIZED_SIZE],
}

#[derive(Clone)]
#[contracttype]
pub struct VerifyingKey {
    pub alpha: [u8; BN254_G1_SERIALIZED_SIZE],
    pub beta: [u8; BN254_G2_SERIALIZED_SIZE],
    pub gamma: [u8; BN254_G2_SERIALIZED_SIZE],
    pub delta: [u8; BN254_G2_SERIALIZED_SIZE],
    pub ic: Vec<[u8; BN254_G1_SERIALIZED_SIZE]>,
}

#[derive(Clone)]
#[contracttype]
pub struct VerifiedProof {
    pub attestation_hash: BytesN<32>,
    pub threshold_cents: u64,
    pub expires_at: u64,
}

pub type Bn254Fr = [u8; BN254_FR_Serialized_SIZE];

#[contracterror]
#[derive(Copy, Clone, Debug, Eq, PartialEq, Ord, PartialOrd)]
#[repr(u32)]
pub enum FundProofError {
    MalformedVerifyingKey = 1,
    MalformedProof = 2,
    PairingError = 3,
    VerificationFailed = 4,
    ProofExpired = 5,
}

const PROOF_KEY: Symbol = symbol_short!("PROOF");

#[contract]
pub struct FundProofVerifier;

#[contractimpl]
impl FundProofVerifier {
    pub fn verify_and_record(
        env: Env,
        proof: Proof,
        pub_signals: Vec<Bn254Fr>,
        attestation_hash: BytesN<32>,
        threshold_cents: u64,
        expires_at: u64,
    ) -> Result<(), FundProofError> {
        if env.ledger().timestamp() >= expires_at {
            return Err(FundProofError::ProofExpired);
        }

        let bn = env.crypto().bn254();
        let vk = vk(&env);

        if pub_signals.len() + 1 != vk.ic.len() {
            return Err(FundProofError::MalformedVerifyingKey);
        }

        let mut vk_x = vk.ic.get(0).unwrap();
        for (s, v) in pub_signals.iter().zip(vk.ic.iter().skip(1)) {
            let prod = bn.g1_mul(&v, &s);
            vk_x = bn.g1_add(&vk_x, &prod);
        }

        let neg_a = env.crypto().bn254_neg_g1(&proof.a);
        let vp1 = soroban_sdk::vec![&env, neg_a, vk.alpha, vk_x, proof.c];
        let vp2 = soroban_sdk::vec![&env, proof.b, vk.beta, vk.gamma, vk.delta];

        if !bn.pairing_check(vp1, vp2) {
            return Err(FundProofError::VerificationFailed);
        }

        env.storage().persistent().set(
            &PROOF_KEY,
            &VerifiedProof {
                attestation_hash,
                threshold_cents,
                expires_at,
            },
        );

        Ok(())
    }

    pub fn get_proof(env: Env, attestation_hash: BytesN<32>) -> Option<VerifiedProof> {
        env.storage().persistent().get(&attestation_hash)
    }
}

fn vk(env: &Env) -> VerifyingKey {
    let mut ic = Vec::new(env);
    for val in VK_IC.iter() {
        ic.push_back(val.clone());
    }
    VerifyingKey {
        alpha: VK_ALPHA.clone(),
        beta: VK_BETA_2.clone(),
        gamma: VK_GAMMA_2.clone(),
        delta: VK_DELTA_2.clone(),
        ic,
    }
}